<template>
  <div class="profile-page"><div class="heading"><span>PROFILE / EDIT</span><h2>个人资料</h2><p>让社区认识镜头背后的你。</p></div><div class="profile-grid"><div class="avatar-area"><a-avatar :src="store.loginUser.userAvatar" :size="108">{{ avatarText }}</a-avatar><strong>{{ store.loginUser.userName || '摄影师' }}</strong><span>你在光影集的摄影身份</span><router-link v-if="store.loginUser.id" :to="'/photographers/' + store.loginUser.id">查看公开主页 ↗</router-link></div><a-form class="profile-form" layout="vertical" :model="form" @finish="save"><a-form-item label="昵称" name="userName" :rules="[{ required: true, message: '请输入昵称' }, { min: 2, message: '昵称至少 2 个字符' }]"><a-input v-model:value="form.userName" maxlength="32" show-count placeholder="希望大家如何称呼你" /></a-form-item><a-form-item label="个人简介"><a-textarea v-model:value="form.userProfile" :rows="5" maxlength="200" show-count placeholder="说说你喜欢拍摄的题材、城市或故事" /></a-form-item><a-form-item label="头像图片地址"><a-input v-model:value="form.userAvatar" placeholder="https://..." /></a-form-item><div class="form-foot"><span>个人简介会显示在你的摄影师主页。</span><a-button type="primary" html-type="submit" :loading="saving">保存资料</a-button></div></a-form></div></div>
</template>
<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { message } from 'ant-design-vue'
import { updateMyProfileUsingPost } from '@/api/userController'
import { useLoginUserStore } from '@/stores/useLoginUserStore'
const store = useLoginUserStore(); const saving = ref(false)
const form = reactive({ userName: '', userAvatar: '', userProfile: '' })
const avatarText = computed(() => (store.loginUser.userName || '摄').slice(0,1))
watch(() => store.loginUser, (user) => { form.userName = user.userName || ''; form.userAvatar = user.userAvatar || ''; form.userProfile = user.userProfile || '' }, { immediate: true, deep: true })
async function save() { saving.value = true; try { const res: any = await updateMyProfileUsingPost({ ...form }); if (res.data.code !== 0) throw new Error(res.data.message); await store.fetchLoginUser(); message.success('资料已保存') } catch (e: any) { message.error(e?.message || '保存失败') } finally { saving.value = false } }
</script>
<style scoped>
.profile-page { max-width: 1000px; margin: 0 auto; padding-inline: var(--gutter); }.heading span { color:var(--text-3); font-size:10px; letter-spacing:.18em; }.heading h2 { margin:7px 0 4px; font-family:var(--font-display); font-weight:400; font-size:30px; }.heading p { color:var(--text-3); margin:0 0 28px; font-size:13px; }.profile-grid { display:grid; grid-template-columns:260px minmax(0,1fr); gap:60px; padding:40px 45px; background:#fff; border:1px solid var(--border); border-radius:6px; }.avatar-area { display:flex; align-items:center; flex-direction:column; padding:18px 0; text-align:center; }.avatar-area strong { margin-top:15px; font-size:17px; font-weight:500; }.avatar-area span { margin-top:4px; color:var(--text-3); font-size:12px; }.avatar-area a { margin-top:25px; color:var(--accent-ink); font-size:12px; }.profile-form { max-width:540px; }.profile-form :deep(.ant-form-item-label) { font-size:13px; }.form-foot { display:flex; justify-content:space-between; align-items:center; gap:15px; border-top:1px solid var(--border); padding-top:20px; }.form-foot span { color:var(--text-3); font-size:12px; }@media(max-width:700px){.profile-grid{grid-template-columns:1fr;gap:25px;padding:25px}.avatar-area{border-bottom:1px solid var(--border)}}
</style>
